PREFIX s: <https://schema.org/>
PREFIX seed: <https://seeds.local/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?item ?id ?title ?status ?revision ?modified ?deferredAt ?deferredBy WHERE {
 GRAPH <https://seeds.local/project/aegis> {
  ?item seed:deferredAt ?deferredAt .
  FILTER(?deferredAt >= '{since}'^^xsd:dateTime)
  OPTIONAL { ?item seed:deferredBy ?deferredBy }
  OPTIONAL { ?item s:identifier ?id }
  OPTIONAL { ?item s:name ?title }
  OPTIONAL { ?item seed:status ?status }
  OPTIONAL { ?item s:version ?revision }
  OPTIONAL { ?item s:dateModified ?modified }
 }
} ORDER BY DESC(?deferredAt) ?item LIMIT 21
